    if not _start_attempt(S, p, 1):
        p['disposition'] = 'refused'
        return _advance(S)
    _save(S)
    _set_next('negotiate')

def _advance(S):
    rest = _undecided(S)
    if rest:
        return _enter_product(S, rest[0])
    if any((p['proposed'] for p in S['products'])):
        return _readback(S)
    for p in S['products']:
        if not p['disposition']:
            p['disposition'] = 'refused'
    _save(S)
    _set_next('finalize')

