        if 'relative' in expr or type(expr.get('day')) is not int:
            return None
        day, month, year = (expr['day'], expr.get('month'), expr.get('year'))
        if not 1 <= day <= 31 or (month is not None and (type(month) is not int or not 1 <= month <= 12)):
