def _time(value):
    try:
        if not isinstance(value, str) or not re.fullmatch('\\d{2}:\\d{2}', value):
            return None
        return datetime.time.fromisoformat(value)
    except Exception:
        return None

def callback_ok(now, date, time, policy):
