    if i >= len(reqs):
        return ''
    r = reqs[i]
    pre = 'Thank you. Before we continue, I need to ask you ' + ('two short security questions. ' if len(reqs) > 1 else 'a short security question. ') if i == 0 else 'Thank you. '
